using BARANG.Core.Api.Errors;
using BARANG.Core.Application.Production;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Production;
using BARANG.Core.Domain.Security;
using Microsoft.AspNetCore.Mvc;
namespace BARANG.Core.Api.Production;
public static class ProductionEndpoints
{
 public static IEndpointRouteBuilder MapProductionEndpoints(this IEndpointRouteBuilder e){RouteGroupBuilder root=e.MapGroup("/api/v1/production");RouteGroupBuilder read=root.MapGroup("").RequireAuthorization(SecurityPermissions.ProductionRead);read.MapGet("/jobs",async([AsParameters]ProductionQueueRequest q,IProductionAdministration s,CancellationToken ct)=>Map(await s.QueueAsync(q.Query(),ct)));read.MapGet("/jobs/{id:guid}",async(Guid id,IProductionAdministration s,CancellationToken ct)=>Map(await s.GetAsync(id,ct)));read.MapGet("/jobs/{id:guid}/history",async(Guid id,IProductionAdministration s,CancellationToken ct)=>Map(await s.HistoryAsync(id,ct)));read.MapGet("/capacity",async(DateTimeOffset?from,DateTimeOffset?to,IProductionAdministration s,CancellationToken ct)=>Map(await s.CapacityAsync(from,to,ct)));read.MapGet("/performance",async(DateTimeOffset?fromUtc,DateTimeOffset?toUtc,IProductionAdministration s,CancellationToken ct)=>Map(await s.PerformanceAsync(fromUtc,toUtc,ct)));read.MapGet("/operators",async(IProductionAdministration s,CancellationToken ct)=>Map(await s.OperatorsAsync(ct)));RouteGroupBuilder shifts=read.MapGroup("/shifts");shifts.MapGet("/",async(bool?includeInactive,IWorkShiftAdministration s,CancellationToken ct)=>Map(await s.ListAsync(includeInactive??false,ct)));shifts.MapPost("/",async(CreateWorkShiftCommand c,IWorkShiftAdministration s,CancellationToken ct)=>Map(await s.CreateAsync(c,ct),true)).RequireAuthorization(SecurityPermissions.OrganizationSettingsManage);shifts.MapPut("/{id:guid}",async(Guid id,UpdateWorkShiftCommand c,IWorkShiftAdministration s,CancellationToken ct)=>Map(await s.UpdateAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.OrganizationSettingsManage);shifts.MapPost("/{id:guid}/activation",async(Guid id,WorkShiftVersionCommand c,IWorkShiftAdministration s,CancellationToken ct)=>Map(await s.SetActiveAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.OrganizationSettingsManage);root.MapPost("/orders/{orderId:guid}/jobs",async(Guid orderId,IProductionAdministration s,CancellationToken ct)=>Map(await s.GenerateAsync(new(orderId),ct),true)).RequireAuthorization(SecurityPermissions.ProductionPlan);root.MapPut("/jobs/{id:guid}/plan",async(Guid id,PlanProductionJobCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.PlanAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionPlan);root.MapPut("/jobs/{id:guid}/operator",async(Guid id,AssignOperatorCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.AssignOperatorAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionAssign);root.MapPut("/jobs/{id:guid}/equipment",async(Guid id,AssignEquipmentCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.AssignEquipmentAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionAssign);root.MapPost("/jobs/{id:guid}/start",async(Guid id,ProductionVersionCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.StartAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.ProductionExecute);root.MapPost("/jobs/{id:guid}/complete",async(Guid id,CompleteProductionJobCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.CompleteAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionExecute);root.MapPost("/jobs/{id:guid}/fail",async(Guid id,ProductionReasonCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.FailAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionExecute);root.MapPost("/jobs/{id:guid}/suspend",async(Guid id,ProductionReasonCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.SuspendAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ProductionExecute);root.MapPost("/jobs/{id:guid}/resume",async(Guid id,ProductionVersionCommand c,IProductionAdministration s,CancellationToken ct)=>Map(await s.ResumeAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.ProductionExecute);return e;}
 private static EndpointResult<T>Map<T>(Result<T>r,bool created=false)=>new(r,created);private sealed class EndpointResult<T>(Result<T>r,bool created):IResult{public Task ExecuteAsync(HttpContext c){if(r.IsSuccess){c.Response.StatusCode=created?201:200;return c.Response.WriteAsJsonAsync(r.Value,c.RequestAborted);}return Results.Problem(ApiProblemDetailsMapper.Create(r.Error,c.TraceIdentifier,c.Request.Path)).ExecuteAsync(c);}}
}
public sealed record ProductionQueueRequest(ProductionJobStatus?Status,ProductionJobType?JobType,Guid?OperatorUserId,Guid?EquipmentId,Guid?BranchId,ProductionPriority?Priority,DateOnly?PlannedDate,int?Page,int?PageSize){public ProductionQueueQuery Query()=>new(Status,JobType,OperatorUserId,EquipmentId,BranchId,Priority,PlannedDate,Page??1,PageSize??20);}
